//! Terminal conformance corpus: recorded and synthetic byte streams
//! (`testdata/conformance/<case>.<cols>.bin`, regenerated by `record.py`) with the
//! screen the `vt100` reference produces for each (`.grid`), and the bytes the host
//! would send a phone that attaches at the end (`.snap`, what `Output::snapshot`
//! builds). The phone's unit tests replay the same files through its own emulator
//! and compare cell by cell, so a divergence between the two shows up on one side.
//!
//! `DESKLINK_BLESS=1 cargo test conformance` rewrites the `.grid`/`.snap` files.
//! Keep this module free of crate imports: it is also built on its own.

use std::path::{Path, PathBuf};

pub(crate) const ROWS: u16 = 30;

fn color(c: vt100::Color) -> String {
    match c {
        vt100::Color::Default => "-".to_string(),
        vt100::Color::Idx(n) => n.to_string(),
        vt100::Color::Rgb(r, g, b) => format!("#{r:02x}{g:02x}{b:02x}"),
    }
}

/// `(offset, cols, rows)` lines of a `.resize` sidecar.
pub(crate) fn parse_resizes(text: &str) -> Vec<(usize, u16, u16)> {
    text.lines()
        .filter_map(|line| {
            let mut parts = line.split_whitespace().map(str::parse::<usize>);
            Some((
                parts.next()?.ok()?,
                u16::try_from(parts.next()?.ok()?).ok()?,
                u16::try_from(parts.next()?.ok()?).ok()?,
            ))
        })
        .collect()
}

pub(crate) fn feed(bytes: &[u8], cols: u16, resizes: &[(usize, u16, u16)]) -> vt100::Parser {
    let mut parser = vt100::Parser::new(ROWS, cols, 0);
    let mut at = 0;
    for &(offset, c, r) in resizes {
        let offset = offset.min(bytes.len());
        parser.process(&bytes[at..offset]);
        parser.screen_mut().set_size(r, c);
        at = offset;
    }
    parser.process(&bytes[at..]);
    parser
}

/// The grid format both sides compare: cursor, one `|` line per row (trailing
/// blanks trimmed), then the non-default style runs.
pub(crate) fn grid(parser: &vt100::Parser) -> String {
    let screen = parser.screen();
    let (rows, cols) = screen.size();
    let (cr, cc) = screen.cursor_position();
    let mut out = format!(
        "size {cols}x{rows}\ncursor {cr} {} visible {} alt {}\n",
        cc.min(cols.saturating_sub(1)),
        u8::from(!screen.hide_cursor()),
        u8::from(screen.alternate_screen()),
    );
    let mut styles = String::new();
    for row in 0..rows {
        let mut text = String::new();
        let mut run: Option<(u16, String)> = None;
        let mut previous = String::new();
        for col in 0..cols {
            let cell = screen.cell(row, col).expect("cell inside the screen");
            if !cell.is_wide_continuation() {
                if cell.has_contents() {
                    text.push_str(cell.contents());
                } else {
                    text.push(' ');
                }
            }
            let mut key = format!("fg={} bg={}", color(cell.fgcolor()), color(cell.bgcolor()));
            for (on, name) in [
                (cell.bold(), " bold"),
                (cell.dim(), " dim"),
                (cell.italic(), " italic"),
                (cell.underline(), " underline"),
                (cell.inverse(), " inverse"),
            ] {
                if on {
                    key.push_str(name);
                }
            }
            if key == "fg=- bg=-" {
                key.clear();
            }
            // A blank cell shows nothing of foreground attributes except a background or inverse.
            if (!cell.has_contents() || cell.contents() == " ") && !cell.is_wide_continuation() {
                let visible = cell.bgcolor() != vt100::Color::Default || cell.inverse();
                if !visible {
                    key.clear();
                }
            }
            // The second half of a wide character is styled with its first.
            if cell.is_wide_continuation() {
                key.clone_from(&previous);
            }
            previous.clone_from(&key);
            match (&mut run, key.is_empty()) {
                (Some((_, k)), false) if *k == key => {}
                (r, _) => {
                    if let Some((start, k)) = r.take() {
                        styles.push_str(&format!("{row},{start}-{}: {k}\n", col - 1));
                    }
                    if !key.is_empty() {
                        *r = Some((col, key));
                    }
                }
            }
        }
        if let Some((start, k)) = run.take() {
            styles.push_str(&format!("{row},{start}-{}: {k}\n", cols - 1));
        }
        out.push('|');
        out.push_str(text.trim_end());
        out.push('\n');
    }
    out.push_str(&styles);
    out
}

/// What `session::Output::snapshot` sends a phone that attaches now.
pub(crate) fn snapshot(parser: &vt100::Parser) -> Vec<u8> {
    let screen = parser.screen();
    let mut out = Vec::from(&b"\x1bc"[..]);
    if screen.alternate_screen() {
        out.extend_from_slice(b"\x1b[?1049h");
    }
    out.extend_from_slice(&screen.state_formatted());
    out
}

pub(crate) fn dir() -> PathBuf {
    if let Some(dir) = std::env::var_os("DL_CONF_DIR") {
        return PathBuf::from(dir);
    }
    Path::new(env!("CARGO_MANIFEST_DIR")).join("src/device_links/pty/testdata/conformance")
}

/// Every case: `(name, cols, bytes, resizes)`.
pub(crate) fn cases() -> Vec<(String, u16, Vec<u8>, Vec<(usize, u16, u16)>)> {
    let mut found = Vec::new();
    let mut entries: Vec<_> = std::fs::read_dir(dir())
        .expect("conformance directory")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .collect();
    entries.sort();
    for path in entries {
        let Some(file) = path.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        let Some(stem) = file.strip_suffix(".bin") else {
            continue;
        };
        let Some((name, cols)) = stem.rsplit_once('.') else {
            continue;
        };
        let Ok(cols) = cols.parse::<u16>() else {
            continue;
        };
        let bytes = std::fs::read(&path).expect("read case");
        let resizes = std::fs::read_to_string(path.with_extension("resize"))
            .map(|t| parse_resizes(&t))
            .unwrap_or_default();
        found.push((name.to_string(), cols, bytes, resizes));
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bless() -> bool {
        std::env::var_os("DESKLINK_BLESS").is_some()
    }

    #[test]
    fn corpus_matches_the_reference_screens() {
        let cases = cases();
        assert!(cases.len() >= 60, "the conformance corpus is missing");
        let mut failures = Vec::new();
        for (name, cols, bytes, resizes) in cases {
            let parser = feed(&bytes, cols, &resizes);
            let got = grid(&parser);
            let base = dir().join(format!("{name}.{cols}"));
            let (grid_path, snap_path) = (base.with_extension("grid"), base.with_extension("snap"));
            if bless() {
                std::fs::write(&grid_path, &got).unwrap();
                std::fs::write(&snap_path, snapshot(&parser)).unwrap();
                continue;
            }
            let want = std::fs::read_to_string(&grid_path).unwrap_or_default();
            if want != got {
                failures.push(format!("{name}.{cols}: grid differs from {}", grid_path.display()));
            }
            // The snapshot must reproduce the screen it was taken from.
            let again = feed(&snapshot(&parser), parser.screen().size().1, &[]);
            if grid(&again) != got {
                failures.push(format!("{name}.{cols}: vt100 does not reproduce its own snapshot"));
            }
            if std::fs::read(&snap_path).unwrap_or_default() != snapshot(&parser) {
                failures.push(format!("{name}.{cols}: stale .snap"));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }
}
